# priprav.ps1 — prepares a Windows laptop for the company-context repositories. Run once; safe to run again.
#
#   irm https://raw.githubusercontent.com/TAKTIK-GROUP/kontext-start/main/priprav.ps1 | iex
#
# Installs what is missing with winget (Git for Windows, Node.js LTS, GitHub CLI, VS Code), logs in
# to GitHub, clones every repository of the organization the person can write to into ~\Kontext,
# installs the Claude Code extension and opens VS Code. Ends with a "PRIPRAVA:" line the person sends
# to the administrator when something fails. Generated by scripts/new-start.mjs from start/ in the
# kit — edit there. KONTEXT_ORG and KONTEXT_PRIECINOK override the organization and the target folder.
#
# Windows PowerShell 5.1 rules this file follows: it runs inside the person's window via iex, so it
# never calls `exit` (that would close the window); human text stays in single-quoted strings and
# avoids typographic single quotes and arrows (PowerShell treats „ “ ” ‘ ’ as string delimiters,
# and a mis-decoded UTF-8 byte can turn into one); no inner double quotes in arguments to native
# commands (5.1 strips them).

function Invoke-KontextPriprava {
  $ErrorActionPreference = 'Continue'
  try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch { }
  # tool output is parsed: no colour codes
  $env:FORCE_COLOR = $null; $env:CLICOLOR_FORCE = $null; $env:GH_FORCE_TTY = $null; $env:NO_COLOR = '1'

  $Org = 'TAKTIK-GROUP'
  if ($env:KONTEXT_ORG) { $Org = $env:KONTEXT_ORG }
  $Dir = Join-Path $HOME 'Kontext'
  if ($env:KONTEXT_PRIECINOK) { $Dir = $env:KONTEXT_PRIECINOK }
  $Extension = 'anthropic.claude-code'
  $SkipRepos = @('kontext-start', 'kontext-sprava')

  function Say($Text) { Write-Host ''; Write-Host $Text -ForegroundColor White }
  function Ok($Text) { Write-Host ('  OK  ' + $Text) -ForegroundColor Green }
  function Info($Text) { Write-Host ('  ' + $Text) }
  function Fail($Code, $Text) { throw ('PRIPRAVA|' + $Code + '|' + $Text) }
  function Test-Cmd($Name) { [bool](Get-Command $Name -ErrorAction SilentlyContinue) }
  function Update-Path {
    $env:Path = [Environment]::GetEnvironmentVariable('Path', 'Machine') + ';' + [Environment]::GetEnvironmentVariable('Path', 'User')
  }
  function Get-NodeMajor {
    if (-not (Test-Cmd 'node')) { return 0 }
    $v = & node -e 'process.stdout.write(String(parseInt(process.versions.node)))' 2>$null
    if ($v -match '^\d+$') { return [int]$v } else { return 0 }
  }
  function Find-Code {
    foreach ($p in @((Join-Path $env:LOCALAPPDATA 'Programs\Microsoft VS Code\bin\code.cmd'), (Join-Path $env:ProgramFiles 'Microsoft VS Code\bin\code.cmd'))) {
      if (Test-Path $p) { return $p }
    }
    $c = Get-Command 'code' -ErrorAction SilentlyContinue
    if ($c) { return $c.Source }
    return $null
  }

  try {
    if ($Org -like '*{{*' -or -not $Org) { Fail 'ORGANIZACIA' 'V skripte chýba názov organizácie na GitHube.' }

    Say 'Príprava notebooku na firemný kontext'
    Info ('Organizácia: ' + $Org + ' · priečinok: ' + $Dir)
    Info 'Trvá to 10–20 minút, väčšinu času sa len sťahuje. Okno nezatváraj.'
    Info 'Ak sa Windows opýta, či povoliť zmeny v zariadení, klikni Áno.'

    if (-not (Test-Cmd 'winget')) {
      Fail 'WINGET' 'Chýba Inštalátor aplikácií (winget). V Microsoft Store nainštaluj alebo aktualizuj „App Installer“ a spusti príkaz znova.'
    }
    Update-Path

    $tools = @(
      @{ Step = '1/6'; Name = 'Git'; Id = 'Git.Git'; Ready = { Test-Cmd 'git' }; Code = 'GIT' },
      @{ Step = '2/6'; Name = 'Node.js'; Id = 'OpenJS.NodeJS.LTS'; Ready = { (Get-NodeMajor) -ge 18 }; Code = 'NODE' },
      @{ Step = '3/6'; Name = 'GitHub CLI'; Id = 'GitHub.cli'; Ready = { Test-Cmd 'gh' }; Code = 'GH_INSTALACIA' },
      @{ Step = '4/6'; Name = 'VS Code'; Id = 'Microsoft.VisualStudioCode'; Ready = { [bool](Find-Code) }; Code = 'VSCODE' }
    )
    foreach ($t in $tools) {
      Say ($t.Step + ' ' + $t.Name)
      if (& $t.Ready) { Ok ($t.Name + ' je nainštalovaný'); continue }
      if ($t.Id -eq 'OpenJS.NodeJS.LTS' -and (Test-Cmd 'node')) {
        Fail 'NODE' 'Na notebooku je príliš stará verzia Node.js (treba 18 alebo novšiu). Ozvi sa správcovi.'
      }
      Info ('Inštalujem ' + $t.Name + '…')
      & winget install --id $t.Id --exact --source winget --silent --accept-package-agreements --accept-source-agreements
      Update-Path
      if (-not (& $t.Ready)) { Fail $t.Code ($t.Name + ' sa nenainštaloval. Spusti príkaz znova; ak sa to zopakuje, ozvi sa správcovi.') }
      Ok ($t.Name + ' je nainštalovaný')
    }
    $Code = Find-Code
    & $Code --install-extension $Extension *> $null
    if ($LASTEXITCODE -eq 0) { Ok 'rozšírenie Claude Code' } else { Info 'Rozšírenie Claude Code nainštaluješ vo VS Code (ponúkne ho samo).' }

    Say '5/6 Prihlásenie do GitHubu'
    & gh auth status --hostname github.com *> $null
    if ($LASTEXITCODE -ne 0) {
      Info 'Teraz sa zobrazí jednorazový kód (napríklad ABCD-1234).'
      Info 'Ak sa niečo opýta, stlač Enter. Otvorí sa prehliadač: prihlás sa do GitHubu,'
      Info 'vlož kód a klikni Authorize. Potom sa vráť sem.'
      & gh auth login --hostname github.com --git-protocol https --web
      if ($LASTEXITCODE -ne 0) { Fail 'PRIHLASENIE' 'Prihlásenie do GitHubu sa nedokončilo. Spusti príkaz znova.' }
    }
    $login = & gh api user --jq .login 2>$null
    Ok ('prihlásený(á) ako ' + $login)
    & gh auth setup-git --hostname github.com *> $null
    if ($LASTEXITCODE -ne 0) { Fail 'PRIHLASENIE' 'Git sa nepodarilo prepojiť s prihlásením do GitHubu.' }

    for ($attempt = 1; $attempt -le 3; $attempt++) {
      $state = & gh api ('user/memberships/orgs/' + $Org) --jq .state 2>$null
      if ($state -eq 'active') { break }
      if ($state -ne 'pending') { Fail 'POZVANKA' ('Nie si členom organizácie ' + $Org + '. Pozvánka mohla prísť na iný e-mail alebo vypršala. Ozvi sa správcovi.') }
      if ($attempt -eq 3) { Fail 'POZVANKA' 'Pozvánka do organizácie stále nie je prijatá.' }
      Info 'Ešte si neprijal(a) pozvánku do firemnej organizácie. Otváram ju v prehliadači.'
      Info 'Klikni Join (ak GitHub žiada dvojstupňové overenie, najprv ho nastav).'
      Start-Process ('https://github.com/orgs/' + $Org + '/invitation')
      [void](Read-Host '  Keď pozvánku prijmeš, stlač tu Enter')
    }
    Ok ('člen(ka) organizácie ' + $Org)

    $name = & git config --global user.name
    if (-not $name) {
      $name = & gh api user --jq .name 2>$null
      while (-not $name) { $name = Read-Host '  Napíš svoje meno a priezvisko a stlač Enter' }
      & git config --global user.name $name
    }
    if (-not (& git config --global user.email)) {
      $id = & gh api user --jq .id
      & git config --global user.email ($id + '+' + $login + '@users.noreply.github.com')
    }
    Ok ('podpis v Gite: ' + (& git config --global user.name))

    Say '6/6 Tvoje repozitáre'
    $repos = @()
    foreach ($full in @(& gh api --paginate 'user/repos?per_page=100' --jq '.[] | select(.permissions.push) | .full_name' 2>$null)) {
      $parts = "$full".Split('/')
      if ($parts.Count -ne 2 -or $parts[0] -ne $Org) { continue }
      if ($SkipRepos -contains $parts[1]) { continue }
      $repos += $parts[1]
    }
    $repos = @($repos | Sort-Object)
    if ($repos.Count -eq 0) { Fail 'ZIADNY_REPOZITAR' ('V organizácii ' + $Org + ' ešte nemáš prístup k žiadnej oblasti. Ozvi sa správcovi.') }
    if ($repos.Count -gt 1) {
      Info 'Môžeš zapisovať do viacerých repozitárov:'
      for ($i = 0; $i -lt $repos.Count; $i++) { Info ('  ' + ($i + 1) + ') ' + $repos[$i]) }
      $pick = Read-Host '  Napíš čísla tých, ktoré chceš stiahnuť (napr. 1 3), alebo len Enter pre všetky'
      $chosen = @()
      foreach ($n in ("$pick" -split '[\s,]+')) {
        if ($n -match '^\d+$' -and [int]$n -ge 1 -and [int]$n -le $repos.Count) { $chosen += $repos[[int]$n - 1] }
      }
      if ($chosen.Count -gt 0) { $repos = $chosen }
    }

    if (-not (Test-Path $Dir)) { [void](New-Item -ItemType Directory -Path $Dir) }
    foreach ($r in $repos) {
      $target = Join-Path $Dir $r
      if (Test-Path (Join-Path $target '.git')) { Ok ($r + ' je už stiahnutý (' + $target + ')'); continue }
      if (Test-Path $target) { Fail 'KLON' ('Priečinok ' + $target + ' už existuje, ale nie je to repozitár. Nič v ňom nemaž, ozvi sa správcovi.') }
      & git clone -q ('https://github.com/' + $Org + '/' + $r + '.git') $target
      if ($LASTEXITCODE -ne 0) { Fail 'KLON' ('Repozitár ' + $r + ' sa nepodarilo stiahnuť.') }
      Ok ($r + ' stiahnutý do ' + $target)
    }

    foreach ($r in $repos) { & $Code (Join-Path $Dir $r) }

    Say 'Hotovo. Vo VS Code sa otvorila tvoja oblasť. Posledné kroky:'
    Info '1. Ak sa VS Code pýta, či dôveruješ autorom priečinka, klikni Yes, I trust the authors.'
    Info '2. Otvor panel Claude (ikona Claude vpravo hore alebo na boku) a prihlás sa firemným účtom.'
    Info '3. Keď sa Claude pýta, či dôveruješ tomuto priečinku, potvrď Yes.'
    Info '4. Napíš „ahoj“. Keď ti asistent odpovie, pošli správcovi tento riadok:'
    $os = [Environment]::OSVersion.Version.ToString()
    $git = (& git --version) -replace 'git version ', ''
    Write-Host ''
    Write-Host ('  PRIPRAVA: OK ' + $login + ' (Windows ' + $os + ', ' + $git + ', Node ' + (& node --version) + ', ' + ($repos -join ' ') + ')')
    Write-Host ''
  } catch {
    $msg = "$($_.Exception.Message)"
    if ($msg -like 'PRIPRAVA|*') {
      $parts = $msg.Split('|', 3)
      $code = $parts[1]; $text = $parts[2]
    } else {
      $code = 'NEOCAKAVANA'; $text = $msg
    }
    Write-Host ''
    Write-Host ('X ' + $text) -ForegroundColor Red
    Write-Host ''
    Write-Host 'Niečo sa nepodarilo. Pošli správcovi tento riadok (a pokojne aj fotku obrazovky):'
    Write-Host ''
    Write-Host ('  PRIPRAVA: CHYBA ' + $code + ' (Windows ' + [Environment]::OSVersion.Version.ToString() + ')')
    Write-Host ''
  }
}

Invoke-KontextPriprava
